import { mapState } from "vuex";
import uploadPictures from "@/components/uploadPictures";
import {
  communityInfoApi,
  communitySaveApi,
  allTopicApi,
} from "@/api/community";
import goodsList from "@/components/goodsList";

export default {
  name: "create",
  components: {
    uploadPictures,
    goodsList,
  },
  data() {
    const validateImage = (rule, value, callback) => {
      if (!value) {
        return callback(new Error("请上传视频封面图"));
      } else {
        callback();
      }
    };
    const validateVideo = (rule, value, callback) => {
      if (!value) {
        return callback(new Error("请上传视频"));
      } else {
        callback();
      }
    };
    return {
      currentTab: "1",
      modals: false,
      gridBtn: {
        xl: 4,
        lg: 8,
        md: 8,
        sm: 8,
        xs: 8,
      },
      gridPic: {
        xl: 6,
        lg: 8,
        md: 12,
        sm: 12,
        xs: 12,
      },
      headeNum: [
        { type: "1", name: "基础设置" },
        { type: "2", name: "关联商品" },
      ],
      topicList: [],
      formValidate: {
        content_type: 1,
        title: "",
        content: "",
        slider_image: [],
        video_url: "",
        image: "",
        topic_id: "",
        product_id: [],
      },
      imageList: [],
      modalPic: false,
      isChoice: "",
      ruleValidate: {
        title: [{ required: true, message: "请输入内容标题", trigger: "blur" }],
        content: [
          { required: true, message: "请输入内容简介", trigger: "blur" },
        ],
        slider_image: [
          {
            required: true,
            message: "请上传图片",
            type: "array",
            trigger: "change",
          },
        ],
        topic_id: [
          {
            required: true,
            message: "请添加话题",
            type: "array",
            trigger: "change",
          },
        ],
        video_url: [
          {
            required: true,
            message: "请上传视频",
            validator: validateVideo,
            trigger: "change",
          },
        ],
        image: [
          {
            required: true,
            validator: validateImage,
            trigger: "change",
          },
        ],
      },
      columns: [
        {
          type: "selection",
          width: 60,
          align: "center",
        },
        {
          title: "商品信息",
          slot: "info",
          minWidth: 300,
        },
        {
          title: "售价",
          key: "price",
          minWidth: 180,
        },
        {
          title: "库存",
          key: "stock",
          minWidth: 180,
        },
        {
          title: "操作",
          slot: "action",
          fixed: "right",
          width: 100,
        },
      ],
      tableData: [],
      id: 0,
      formSelection: [],
      typeTit: "",
    };
  },
  computed: {
    ...mapState("admin/layout", ["isMobile", "menuCollapse"]),
    labelWidth() {
      return this.isMobile ? undefined : 90;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
  },
  created() {
    this.allTopicList();
    this.id = this.$route.params.id || 0;
    if (this.id) {
      this.getInfo();
    }
  },
  methods: {
    // 控制话题
    topicSelect(data) {
      if (data.length > 5) {
        this.$Message.warning("最多只能选五层！");
        data.pop();
      }
    },
    // 话题列表；
    allTopicList() {
      allTopicApi()
        .then((res) => {
          this.topicList = res.data;
        })
        .catch((err) => {
          this.$Message.error(err.msg);
        });
    },
    delVideo() {
      let that = this;
      that.$set(that.formValidate, "video_url", "");
      this.$refs.formValidate.validateField("video_url");
    },
    del(row) {
      this.tableData.forEach((item, index) => {
        if (row.id === item.id) {
          return this.tableData.splice(index, 1);
        }
      });
      this.formSelection = [];
    },
    batchDel() {
      for (var i = 0; i < this.formSelection.length; i++) {
        for (var j = 0; j < this.tableData.length; j++) {
          if (this.tableData[j].id === this.formSelection[i].id) {
            this.tableData.splice(j, 1);
            j--;
          }
        }
      }
      this.formSelection = [];
    },
    selectChange(data) {
      this.formSelection = data;
    },
    addGoods() {
      this.modals = true;
    },
    cancel() {
      this.modals = false;
    },
    getProductId(data) {
      this.modals = false;
      let list = this.tableData.concat(data);
      this.tableData = this.unique(list, "id");
    },
    //内容详情
    getInfo() {
      communityInfoApi(this.id)
        .then((res) => {
          this.formValidate = res.data;
          this.formValidate.topic_id = res.data.topic.map((item) => {
            return item.id;
          });
          this.tableData = res.data.product;
        })
        .catch((err) => {
          this.$Message.error(err.msg);
        });
    },
    upTab() {
      this.currentTab = "1";
    },
    downTab(name) {
      this.$refs[name].validate((valid) => {
        if (valid) {
          this.currentTab = "2";
        } else {
          this.$Message.warning("请完善数据");
        }
      });
    },
    //保存内容
    handleSubmit(name) {
      this.$refs[name].validate((valid) => {
        if (valid) {
          let product_id = [];
          if (this.tableData && this.tableData.length) {
            this.tableData.forEach((item) => {
              product_id.push(item.id);
            });
          }
          this.formValidate.product_id = product_id;
          if (this.formValidate.content_type == 1) {
            this.formValidate.image = this.formValidate.slider_image[0];
          }
          communitySaveApi(this.formValidate, this.id)
            .then((res) => {
              this.$router.push({ path: "/admin/content/community/content" });
              this.$Message.success(res.msg);
            })
            .catch((err) => {
              this.$Message.error(err.msg);
            });
        } else {
          this.$Message.warning("请完善数据");
        }
      });
    },
    // 点击商品图
    modalPicTap(tit, type) {
      this.typeTit = type;
      this.modalPic = true;
      this.isChoice = tit === "dan" ? "单选" : "多选";
    },
    // 获取单张图片信息
    getPic(pc) {
      this.modalPic = false;
      if (this.typeTit == "image") {
        this.formValidate.image = pc.att_dir;
        this.$refs.formValidate.validateField("image");
      } else {
        this.formValidate.video_url = pc.att_dir;
        this.$refs.formValidate.validateField("video_url");
      }
    },
    //对象数组去重；
    unique(arr, id) {
      const res = new Map();
      return arr.filter((arr) => !res.has(arr[id]) && res.set(arr[id], 1));
    },
    // 获取多张图信息
    getPicD(pc) {
      this.imageList = this.imageList.concat(pc);
      let uni = this.unique(this.imageList, "att_id");
      uni.map((item) => {
        this.formValidate.slider_image.push(item.att_dir);
      });
      this.modalPic = false;
    },
    handleRemove() {
      this.formValidate.image = "";
      this.$refs.formValidate.validateField("image");
    },
    handleRemove2(i) {
      this.formValidate.slider_image.splice(i, 1);
    },
  },
};
